INSERT INTO changelog (title, body, created_at) VALUES ('Стартапи: «будинок» продукту — база знань і журнал проблем', 'Стартап тепер буває двох типів: «Свій продукт» або «Рішення для клієнта» (напр. CRM для Аква Віти). Тип видно в шапці, міняється в «Редагувати». Проєкти з Лабораторії з клієнтом стають «для клієнта» самі.
Нова вкладка «База знань» — памʼять проєкту: що ламалось і як виправили, як підключали API (Binotel, Zadarma…), уроки, що побачили у відділу продажу. Джері записує туди сам, коли ви щось розібрали. База знань іде в експорт проєкту для Claude Code.
Нова вкладка «Проблеми» — сюди продукт сам надсилає помилки і відгуки користувачів (кнопка «Щось не працює»). Біля кожної: «Промпт для Claude Code» (готове завдання виправити), «Беру в роботу», «✓ Виправлено» з поясненням (воно лягає в базу знань). Нова проблема — повідомлення тобі в Telegram (тумблер у «Можливостях»). Щоб продукт почав слати звіти: вкладка «Проблеми» → «Підключити продукт до журналу» → скопіюй промпт у Claude Code в репозиторії продукту (там ключ проєкту — не публікуй).', datetime('now'));
